package dev.kelmagic.mixin;
import net.minecraft.world.level.block.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.core.BlockPos;import net.minecraft.world.level.block.state.BlockState;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.*;
/** Ownerless vanilla automation cannot bypass personal research. Baseline/vanilla recipes remain usable. */
@Mixin(CrafterBlock.class)public abstract class ResearchCrafterMixin {
 @Inject(method="dispenseFrom",at=@At("HEAD"),cancellable=true)private void gate(BlockState state,ServerLevel l,BlockPos pos,CallbackInfo ci){if(!(l.getBlockEntity(pos) instanceof net.minecraft.world.level.block.entity.CrafterBlockEntity crafter))return;var list=new java.util.ArrayList<net.minecraft.world.item.ItemStack>();for(int i=0;i<9;i++)list.add(crafter.getItem(i));var recipe=CrafterBlock.getPotentialResults(l,net.minecraft.world.item.crafting.CraftingInput.of(3,3,list));if(recipe.isEmpty())return;var out=recipe.get().value().assemble(net.minecraft.world.item.crafting.CraftingInput.of(3,3,list),l.registryAccess());var id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(out.getItem());if(id.getNamespace().equals("kelmagic")&&!java.util.Set.of("mana_core","archivists_codex","archivist_table").contains(id.getPath())){l.levelEvent(1050,pos,0);ci.cancel();}}
}
